package org.apache.commons.math.linear;

import java.io.*;
import java.io.Serializable;
import java.math.*;
import java.util.*;
import org.apache.commons.math.util.MathUtils;
import org.junit.*;
import org.junit.Assert;
import org.junit.Test;
import static org.junit.Assert.*;

/**
 * Unit tests for RealMatrixImpl#operate
 */
public class RealMatrixImpl_operate_TriageGen1Test {

    private static final double EPSILON = 1e-10;

    @Test
    public void testOperateWithValidInput() {
        // Matrix:
        // [ 1.0, 2.0 ]
        // [ 3.0, 4.0 ]
        double[][] data = {
            {1.0, 2.0},
            {3.0, 4.0}
        };
        RealMatrixImpl matrix = new RealMatrixImpl(data);

        // Vector v: [0.5, 1.5]
        // Calculation:
        // Row 0: (1.0 - 0.5) + (2.0 - 1.5) = 0.5 + 0.5 = 1.0
        // Row 1: (3.0 - 0.5) + (4.0 - 1.5) = 2.5 + 2.5 = 5.0
        double[] v = {0.5, 1.5};
        double[] expected = {1.0, 5.0};

        double[] actual = matrix.operate(v);

        Assert.assertArrayEquals(expected, actual, EPSILON);
    }

    @Test
    public void testOperateWithSingleElementMatrix() {
        // Matrix: [ 10.0 ]
        double[][] data = {{10.0}};
        RealMatrixImpl matrix = new RealMatrixImpl(data);

        // Vector v: [2.0]
        // Calculation: (10.0 - 2.0) = 8.0
        double[] v = {2.0};
        double[] expected = {8.0};

        double[] actual = matrix.operate(v);

        Assert.assertArrayEquals(expected, actual, EPSILON);
    }

    @Test
    public void testOperateWithRectangularMatrix() {
        // Matrix (2x3):
        // [ 1, 1, 1 ]
        // [ 2, 2, 2 ]
        double[][] data = {
            {1.0, 1.0, 1.0},
            {2.0, 2.0, 2.0}
        };
        RealMatrixImpl matrix = new RealMatrixImpl(data);

        // Vector v: [1, 1, 1]
        // Row 0: (1-1) + (1-1) + (1-1) = 0
        // Row 1: (2-1) + (2-1) + (2-1) = 3
        double[] v = {1.0, 1.0, 1.0};
        double[] expected = {0.0, 3.0};

        double[] actual = matrix.operate(v);

        Assert.assertArrayEquals(expected, actual, EPSILON);
    }

    @Test(expected = IllegalArgumentException.class)
    public void testOperateWithWrongVectorLength() {
        // Matrix (2x2)
        double[][] data = {
            {1.0, 2.0},
            {3.0, 4.0}
        };
        RealMatrixImpl matrix = new RealMatrixImpl(data);

        // Vector length 3 (should be 2)
        double[] v = {1.0, 2.0, 3.0};

        matrix.operate(v);
    }

    @Test(expected = IllegalArgumentException.class)
    public void testOperateWithEmptyVectorLength() {
        // Matrix (1x1)
        double[][] data = {{1.0}};
        RealMatrixImpl matrix = new RealMatrixImpl(data);

        // Vector length 0 (should be 1)
        double[] v = {};

        matrix.operate(v);
    }

    @Test
    public void testOperateWithNegativeValues() {
        // Matrix:
        // [-1, -2]
        double[][] data = {{-1.0, -2.0}};
        RealMatrixImpl matrix = new RealMatrixImpl(data);

        // Vector v: [-5, -10]
        // Calculation: (-1 - (-5)) + (-2 - (-10)) = 4 + 8 = 12
        double[] v = {-5.0, -10.0};
        double[] expected = {12.0};

        double[] actual = matrix.operate(v);

        Assert.assertArrayEquals(expected, actual, EPSILON);
    }
}
